def calculate_discount(price, member_level, campaign=False):
    if price < 0:
        raise ValueError('Price must be non-negative.')

    discount_coefficients = {
        'normal': 1.0,
        'silver': 0.95,
        'gold': 0.90
    }

    if member_level not in discount_coefficients:
        raise ValueError(f'Invalid member level: {member_level}. Valid levels are normal, silver, and gold.')

    base_price = price * discount_coefficients[member_level]

    if campaign:
        base_price *= 0.90

    return round(base_price, 2)

