from typing import List

def deduplicate_orders(orders: List[dict]) -> List[dict]:
    if not orders:
        return []
    updated_dict = {}
    for order in reversed(sorted(orders, key=lambda x: (x['id'], -x['updated_at']))):
        id_ = order['id']
        if id_ not in updated_dict or updated_dict[id_] < order['updated_at']:
            updated_dict[id_] = order['updated_at']
    result = [order for _, order in sorted(updated_dict.items(), key=lambda item: item[0])]  # 按 id 字符串升序排列
    return result

