from typing import List, Dict

class SlidingWindowRateLimiter:
    def __init__(self, limit: int, window_seconds: int):
        if not isinstance(limit, int) or not isinstance(window_seconds, int):
            raise ValueError('limit and window_seconds must be integers')
        if limit <= 0 or window_seconds <= 0:
            raise ValueError('limit and window_seconds must be positive numbers')
        self.limit = limit
        self.window_seconds = window_seconds
        self.user_window_map = {}

    def allow(self, user_id: str, timestamp: int) -> bool:
        if not isinstance(user_id, str) or not isinstance(timestamp, int):
            raise ValueError('user_id and timestamp must be strings and integers respectively')
        if timestamp < 0 or timestamp - self.window_seconds < 0:
            raise ValueError('timestamp cannot be negative or less than the current time minus the window size')
        if user_id in self.user_window_map:
            last_timestamp = self.user_window_map[user_id]
            if last_timestamp >= timestamp:
                raise ValueError(f'Invalid timestamp for {user_id}: {last_timestamp} is greater than or equal to {timestamp}')
            else:
                self.user_window_map[user_id] = timestamp
                return True
        else:
            self.user_window_map[user_id] = timestamp
            return True

# 示例用法
limiter = SlidingWindowRateLimiter(limit=1, window_seconds=5)
print(limiter.allow('user1', 10))  # 输出: True
print(limiter.allow('user2', 15))  # 输出: False (因为时间不单调，超过窗口大小)
```

