class SlidingWindowRateLimiter:

    def __init__(self, limit: int, window_seconds: float):
        if not (limit > 0 and isinstance(limit, int)) or not (window_seconds > 0 and isinstance(window_seconds, (int, float))):
            raise ValueError('Limit and window seconds must be positive numbers.')

        self.limit = limit
        self.window_seconds = window_seconds
        self.user_limits = {}

    def allow(self, user_id: str, timestamp: float) -> bool:
        if 'last_timestamp' in self.user_limits.get(user_id, {}):
            last_timestamp = self.user_limits[user_id]['last_timestamp']
            if timestamp < last_timestamp:
                raise ValueError('Timestamps for the same user must be non-decreasing.')

        current_window_start = max(0, timestamp - self.window_seconds)
        count_in_current_window = 0

        # Count requests within the current sliding window
        for t in range(int(current_window_start), int(timestamp + 1)):
            if t in self.user_limits.get(user_id, {}).get('requests', []):
                count_in_current_window += 1

        if count_in_current_window >= self.limit:
            return False

        # Update or initialize request list and last_timestamp
        if user_id not in self.user_limits:
            self.user_limits[user_id] = {'last_timestamp': timestamp}
        else:
            self.user_limits[user_id]['last_timestamp'] = max(self.user_limits[user_id].get('last_timestamp'), timestamp)

        # Add the current timestamp to the requests list for this user
        if 'requests' not in self.user_limits[user_id]:
            self.user_limits[user_id]['requests'] = []
        self.user_limits[user_id]['requests'].append(timestamp)

        return True

