class SlidingWindowRateLimiter:

    def __init__(self, limit: int, window_seconds: float):
        if not isinstance(limit, (int, float)) or limit <= 0:
            raise ValueError('limit must be a positive number')
        if not isinstance(window_seconds, (int, float)) or window_seconds <= 0:
            raise ValueError('window_seconds must be a positive number')

        self.limit = limit
        self.window_seconds = window_seconds
        self.user_limits = {}

    def allow(self, user_id: str, timestamp: float) -> bool:
        # Check for monotonicity of timestamps
        if user_id in self.user_limits and timestamp < self.user_limits[user_id][-1]:
            raise ValueError('Timestamps must be non-decreasing for each user')

        # Update the last seen time for this user
        if user_id not in self.user_limits:
            self.user_limits[user_id] = [timestamp]
        else:
            self.user_limits[user_id].append(timestamp)

        # Calculate the number of requests within the window
        start_time = max(0, timestamp - self.window_seconds)
        request_count = sum(1 for t in self.user_limits[user_id] if t >= start_time)

        # Check if we have exceeded the limit
        return request_count < self.limit

