    if len_diff > 0:
        parts_b.extend([0] * len_diff)
    elif len_diff < 0:
        parts_a.extend([0] * abs(len_diff))

    # 比较每个段数
    for part_a, part_b in zip(parts_a, parts_b):
        if part_a != part_b:
            return 1 if part_a > part_b else -1

    return 0

